%TEST_V17_PORT  Verify the v17 MATLAB port against golden vectors.
%
%   Run in MATLAB:
%       cd <this folder>
%       test_v17_port
%
%   Expected: all four checks PASS.
%   Golden vectors were generated by verify_v17_port.py:
%   numpy mirror of these exact .m files vs the PyTorch reference
%   (model_v14.py, v17 best checkpoint E330).

net = v17_damper_init();
G = load('golden_vectors.mat');

%% [1] forward, 1 ms steps
st = v17_new_state(net);
N = numel(G.fwd_F_ref);
F = zeros(N, 1);
for t = 1:N
    [F(t), st] = v17_damper_step(net, G.fwd_x(t), G.fwd_v(t), G.fwd_a(t), ...
        G.fwd_I(t), 0, G.fwd_T(t), 0.001, st);
end
e1 = max(abs(F - G.fwd_F_ref));
fprintf('[1] forward 1ms x%d: max|err| = %.3e N  %s\n', N, e1, passfail(e1 < 1e-6));

%% [2] forward, macro dt=0.01 (10 substeps, ZOH)
st = v17_new_state(net);
M = numel(G.macro_F_ref);
Fm = zeros(M, 1);
for b = 1:M
    t = (b-1)*10 + 1;
    [Fm(b), st] = v17_damper_step(net, G.fwd_x(t), G.fwd_v(t), G.fwd_a(t), ...
        G.fwd_I(t), 0, G.fwd_T(t), 0.01, st);
end
e2 = max(abs(Fm - G.macro_F_ref));
fprintf('[2] forward macro dt=0.01: max|err| = %.3e N  %s\n', e2, passfail(e2 < 1e-6));

%% [3] inverse bisection
e3 = 0;
for k = 1:numel(G.inv_I_ref)
    st_k = struct('h', G.inv_h(k, :, :), 'ie_buf', zeros(net.lag_kmax, 1));
    st_k.h = reshape(st_k.h, 2, 16);
    [I_cmd, ~] = v17_inverse_bisection(net, G.inv_Fdes(k), G.inv_x(k), ...
        G.inv_v(k), G.inv_a(k), G.inv_T(k), st_k);
    e3 = max(e3, abs(I_cmd - G.inv_I_ref(k)));
end
fprintf('[3] inverse bisection x%d: max|err| = %.3e A  %s\n', ...
    numel(G.inv_I_ref), e3, passfail(e3 < 1e-6));

%% [4] inverse head
e4 = 0;
for k = 1:numel(G.head_I_ref)
    st_k = struct('h', reshape(G.inv_h(k, :, :), 2, 16), ...
                  'ie_buf', zeros(net.lag_kmax, 1));
    I_cmd = v17_inverse_head(net, G.inv_Fdes(k), G.inv_x(k), ...
        G.inv_v(k), G.inv_a(k), G.inv_T(k), st_k);
    e4 = max(e4, abs(I_cmd - G.head_I_ref(k)));
end
fprintf('[4] inverse head x%d: max|err| = %.3e A  %s\n', ...
    numel(G.head_I_ref), e4, passfail(e4 < 1e-9));

function s = passfail(ok)
if ok, s = 'PASS'; else, s = 'FAIL'; end
end
